/* Client report projection: edits never change contracts or investment records. */
window.CrmCompleteReport=(()=>{
 const same=(a,b)=>String(a)===String(b),copy=x=>structuredClone(x);
 let draft=null,owner=null,mailDraft=null;
 const names={contracts:'Smlouvy a ochrana',loans:'Úvěry a financování',investments:'Investice a FKI',pensions:'Penze a budoucí příjem',closing:'Další krok pro Vaši rodinu'};
 const date=v=>v?clientOutput_xDate(v):'Neuvedeno';
 const money=v=>v===''||v==null?'Neuvedeno':clientOutput_xMoney(v);
 const key=x=>[x.area,x.key||x.isin,x.company,x.product].join('|');
 const tone=(c,d)=>d.toneOverride||c.communicationTone||'formal';
 const informal=text=>text.replaceAll('Vaší situací','Tvou situací').replaceAll('Vašich cílech','Tvých cílech').replaceAll('Vás zajímá','Tě zajímá').replaceAll('Vaši blízcí','Tvoji blízcí').replaceAll('kdybyste jim nemohli vše vysvětlit sami','kdybys jim nemohl/a vše vysvětlit osobně').replaceAll('Vám to dává','Ti to dává').replaceAll('vyplňte krátký','vyplň krátký').replaceAll('mi pošlete zpět','mi pošli zpět').replaceAll('Nezavazuje Vás','Nezavazuje Tě');
 function syncTone(c,d){const base=defaults(c),isInformal=tone(c,d)==='informal';for(const g of Object.keys(base.notes)){if(d.notes[g]===base.notes[g]||d.notes[g]===informal(base.notes[g]))d.notes[g]=isInformal?informal(base.notes[g]):base.notes[g];}if(d.closing===base.closing||d.closing===informal(base.closing))d.closing=isInformal?informal(base.closing):base.closing;return d;}
 function defaults(c){
  const contracts=clientContracts(c.id);
  return {version:1,toneOverride:'',investmentDetails:false,requestId:crypto.randomUUID(),contact:{name:clientName(c),address:c.address||'',phone:c.phone||'',email:c.email||''},sections:Object.fromEntries(Object.keys(names).map(k=>[k,true])),rows:{
   contracts:contracts.map(s=>({id:String(s.id),selected:true,product:s.product||s.type||'',company:s.company||'',number:s.number||'',date:s.anniv||'',payment:s.amount??''})),
   loans:contracts.filter(s=>clientOutput_xContracts(c,'loans').some(x=>same(x.id,s.id))||/staveb/.test(norm([s.type,s.product].join(' ')))).map(s=>({id:String(s.id),selected:true,product:s.product||s.type||'',company:s.company||'',initial:s.initialAmount??s.originalAmount??s.principal??s.volume??'',date:s.startDate||s.dealDate||'',payment:s.monthlyPayment??s.payment??s.amount??'',day:s.paymentDay||'',note:''})),
   investments:clientOutput_xClientInvestments(c).map(x=>({id:key(x),selected:true,product:x.product,company:x.company,note:''})).concat(clientOutput_xPendingInvestments(c).map(x=>({id:'pending|'+x.kind+'|'+x.id,selected:true,product:x.product+' · čeká na připsání',company:x.company,note:''}))),
   pensions:clientOutput_xPensions(c).map(x=>({id:x.kind+'-'+x.id,selected:true,product:x.product,company:x.company,date:x.source.startDate||x.source.dealDate||(x.kind==='deal'?x.date:'')||'',value:pensionCurrentValue(x.source,x.kind)??'',valueDate:x.source.pensionValueDate||x.source.valueDate||'',note:''}))
  },notes:{contracts:'Přehled sjednaných služeb pomáhá hlídat výročí a udržovat smlouvy v souladu s Vaší situací.',loans:'Na jednom místě vidíme pravidelné splátky a můžeme včas plánovat další financování.',investments:'Společně sledujeme, jak peníze pracují na Vašich cílech. Výběry jsou v přehledu oddělené od výnosu.',pensions:'Dlouhodobá rezerva může doplnit budoucí státní důchod.'},closing:'Děkuji za důvěru a dosavadní spolupráci. Společně majetek budujeme a chráníme. Možná Vás zajímá i to, zda by se v něm Vaši blízcí vyznali, kdybyste jim nemohli vše vysvětlit sami. Dědický a krizový plán pomůže ujasnit, co rodina potřebuje vědět a co připravit. Pokud Vám to dává smysl, vyplňte krátký dotazník. Odpovědi mi pošlete zpět a na další schůzce je společně projdeme. Nezavazuje Vás to k žádné službě.'};
 }
 function load(c){const fresh=defaults(c),old=c.completeClientReport;if(!old)return fresh;for(const group of Object.keys(fresh.rows))fresh.rows[group]=fresh.rows[group].map(row=>(()=>{const saved=old.rows?.[group]?.find(x=>x.id===row.id);if(!saved)return row;return {...row,selected:saved.selected,note:saved.note||'',_edited:saved._edited||[],...Object.fromEntries((saved._edited||[]).map(k=>[k,saved[k]]))};})());return {...fresh,...old,rows:fresh.rows,contact:{...fresh.contact,...Object.fromEntries((old.contactEdited||[]).map(k=>[k,old.contact?.[k]??fresh.contact[k]]))},sections:{...fresh.sections,...old.sections},notes:{...fresh.notes,...old.notes}};}
 const cols={contracts:{product:'Smlouva',company:'Společnost',payment:'Platba (Kč)',number:'Číslo smlouvy',date:'Výročí'},loans:{product:'Produkt',company:'Společnost',initial:'Počáteční výše (Kč)',date:'Datum sjednání',payment:'Měsíční splátka / vklad (Kč)',day:'Den platby',note:'Co služba řeší / poznámka'},investments:{product:'Fond',company:'Společnost',note:'Poznámka pro klienta'},pensions:{product:'Produkt / strategie',company:'Společnost',date:'Od kdy',value:'Aktuální hodnota (Kč)',valueDate:'Hodnota k datu',note:'Poznámka'}};
 function input(path,v,type='text'){return `<input data-report-path="${esc(path)}" type="${type}" ${type==='number'?'step="any"':''} value="${esc(v??'')}">`;}
 function open(id){const c=findClient(id);if(!c)return;owner=c.id;draft=syncTone(c,load(c));crmExtraModal('completeReport','Export klientských dat · '+clientName(c),`<p class="note">Vyberte, co klient uvidí. Úpravy níže platí pro tento přehled; nemění evidenci smluv. Rodné číslo ani datum narození se nepřebírají. Chybějící údaje můžete doplnit, prázdná částka není nula.</p><label class=field>Oslovení v přehledu<select data-report-path="toneOverride"><option value="" ${!draft.toneOverride?'selected':''}>Podle karty klienta · ${c.communicationTone==='informal'?'tykání':'vykání'}</option><option value="informal" ${draft.toneOverride==='informal'?'selected':''}>Tykání</option><option value="formal" ${draft.toneOverride==='formal'?'selected':''}>Vykání</option></select></label><p class=note>Volba platí pro tento export i navazující dotazník. Vlastní texty zůstávají zachované a můžete je upravit níže.</p><div class="form-grid">${Object.entries({name:'Jméno',address:'Adresa',phone:'Telefon',email:'E-mail'}).map(([k,l])=>`<label class=field>${l}${input('contact.'+k,draft.contact[k])}</label>`).join('')}</div>${Object.entries(cols).map(([g,fields])=>`<details open><summary><label><input type=checkbox data-report-path="sections.${g}" ${draft.sections[g]?'checked':''}> ${names[g]}</label></summary>${g==='investments'?`<label><input type=checkbox data-report-path="investmentDetails" ${draft.investmentDetails?'checked':''}> Přidat podrobnosti fondů a transakce (delší výstup)</label>`:''}<label class=field>Úvod pro klienta<textarea data-report-path="notes.${g}">${esc(draft.notes[g]||'')}</textarea></label>${draft.rows[g].map((r,i)=>`<details class=mini-card><summary><label><input type=checkbox data-report-path="rows.${g}.${i}.selected" ${r.selected?'checked':''}> ${esc(r.product)} · ${esc(r.company)}</label></summary><div class=form-grid>${Object.entries(fields).map(([k,l])=>g==='investments'&&k!=='note'?`<p>${l}: ${esc(r[k])}</p>`:`<label class=field>${l}${input('rows.'+g+'.'+i+'.'+k,r[k],['date','valueDate'].includes(k)?'date':['value','initial','payment'].includes(k)?'number':'text')}</label>`).join('')}</div></details>`).join('')||'<p class=note>V této části zatím není evidovaná položka.</p>'}</details>`).join('')}<details open><summary><label><input type=checkbox data-report-path="sections.closing" ${draft.sections.closing?'checked':''}> Poděkování a dědický / krizový plán</label></summary><textarea data-report-path="closing" rows=5 style="width:100%">${esc(draft.closing)}</textarea><p class=note>Osobní odkaz vede na dotazník Majetek a plán. Odpovědi se po nahrání přiřadí podle odkazu ke klientovi.</p></details><div class=actions><button class=btn onclick="CrmCompleteReport.save()">Uložit nastavení</button><button class=btn onclick="CrmCompleteReport.preview()">Náhled / PDF</button><button class="btn primary" onclick="CrmCompleteReport.download()">Stáhnout HTML</button><button class="btn" onclick="CrmCompleteReport.prepareMail()">Připravit e-mail klientovi</button></div><p class=note>V náhledu zvolte Tisk / Uložit PDF. Jednotlivé části začínají na nové stránce, dlouhé seznamy mohou pokračovat na další. Připravený report nic neodesílá.</p>${history(c)}`);document.getElementById('completeReport').oninput=edit;document.getElementById('completeReport').onchange=edit;}
 function edit(e){const path=e.target.dataset.reportPath;if(!path||!draft)return;const parts=path.split('.');let target=draft;for(const part of parts.slice(0,-1))target=target[part];target[parts.at(-1)]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(path==='toneOverride'){syncTone(findClient(owner),draft);document.querySelectorAll('#completeReport textarea[data-report-path]').forEach(el=>{const k=el.dataset.reportPath;el.value=k==='closing'?draft.closing:draft.notes[k.split('.')[1]];});}if(parts[0]==='contact')draft.contactEdited=[...new Set([...(draft.contactEdited||[]),parts.at(-1)])];if(parts[0]==='rows'&&parts.at(-1)!=='selected'){target._edited=[...new Set([...(target._edited||[]),parts.at(-1)])];}}
 function familyLink(c,d){const fields={clientName:d.contact.name,email:d.contact.email,phone:d.contact.phone,address:d.contact.address};const ctx={fields,tone:tone(c,d),brand:clientManagementId(c)==='mantra'?'mantra':'fairlife'};let binary='';new TextEncoder().encode(JSON.stringify(ctx)).forEach(b=>binary+=String.fromCharCode(b));return 'https://filipsolar202-blip.github.io/filip-crm/assets/family-plan/dotaznik.html?v=2026.11.18-4#request='+encodeURIComponent(d.requestId)+'&context='+encodeURIComponent(btoa(binary));}
 function save(){const c=findClient(owner);if(!c||!draft)return false;const before=copy(state);c.completeClientReport=copy(draft);c.completeClientReport.updatedAt=new Date().toISOString();if(draft.sections.closing){c.clientForms||=[];if(!c.clientForms.some(r=>r.id===draft.requestId))c.clientForms.push({id:draft.requestId,formId:'family',source:'client-report',name:'Zájem o dědický a krizový plán',url:familyLink(c,draft),updatedAt:new Date().toISOString(),responses:[]});const request=c.clientForms.find(r=>r.id===draft.requestId);if(request?.source==='client-report'){request.url=familyLink(c,draft);request.updatedAt=new Date().toISOString();}}if(!persist()){state=before;return false;}saveToast('Nastavení reportu uloženo');return true;}
 function html(c,d){
  d=syncTone(c,copy(d));const t=(formal,informal)=>tone(c,d)==='informal'?informal:formal;const isMantra=clientManagementId(c)==='mantra';

  const investments=clientOutput_xClientInvestments(c).filter(x=>d.rows.investments.some(r=>r.selected&&r.id===key(x)));
  const investmentHtml=clientOutput_xReportHtml(c,{summary:true,investments:true,fki:true,pending:true,notice:true,onlyInvestmentKeys:investments.map(key),onlyPendingKeys:d.rows.investments.filter(r=>r.selected&&r.id.startsWith('pending|')).map(r=>r.id.slice(8))},'');
  const doc=new DOMParser().parseFromString(investmentHtml,'text/html');
  doc.querySelector('.hero')?.remove();doc.querySelector('.print')?.remove();if(!d.investmentDetails){doc.querySelectorAll('.report-fund-details,.report-provider-block').forEach(e=>e.remove());}doc.querySelectorAll('.report-area-banner').forEach(e=>e.hidden=true);if(!d.investmentDetails)doc.querySelectorAll('.report-fund-overview a').forEach(e=>e.removeAttribute('href'));
  // Only chosen investments are embedded; report controls cannot reveal omitted holdings.
  const styles=[...doc.querySelectorAll('style')].map(s=>s.textContent).join('\n'),scripts=[...doc.querySelectorAll('script')].map(s=>s.outerHTML).join('');doc.querySelectorAll('script').forEach(s=>s.remove());
  const inv=doc.querySelector('.wrap')?.innerHTML||'';
  let page=0;const section=(g,body)=>`<section class="complete-page complete-${g}"><div class=eyebrow>${String(++page).padStart(2,'0')} / ${esc(g==='closing'?t(names[g],'Další krok pro Tvou rodinu'):names[g])}</div><h2>${esc(g==='closing'?t(names[g],'Další krok pro Tvou rodinu'):names[g])}</h2>${d.notes[g]?`<p class=lead>${esc(d.notes[g])}</p>`:''}${body}</section>`;
  const table=(headers,rows)=>`<div class=table-wrap><table><thead><tr>${headers.map(h=>'<th>'+esc(h)+'</th>').join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')||'<tr><td colspan='+headers.length+'>Bez vybraných položek.</td></tr>'}</tbody></table></div>`;
  const contact=`<header class="complete-contact"><div class="complete-brand"><div>${isMantra?'<img alt="Mantra" class="complete-logo mantra" src="data:image/png;base64,">':'<img alt="FairLife" class="complete-logo" src="data:image/jpeg;base64,"><span class="complete-advisor">Filip Solár</span>'}</div><span class=eyebrow>Vytvořeno ${date(today())}</span></div><h1>${esc(d.contact.name)}</h1><p>${[d.contact.address,d.contact.phone,d.contact.email].filter(Boolean).map(esc).join(' · ')}</p><h2>${t('Váš finanční přehled','Tvůj finanční přehled')}</h2></header>`;
  let content=contact;
  if(d.sections.contracts)content+=section('contracts',table(['Smlouva','Společnost','Platba','Číslo smlouvy','Výročí'],d.rows.contracts.filter(r=>r.selected).map(r=>[r.product,r.company,money(r.payment),r.number,date(r.date)])));
  if(d.sections.loans)content+=section('loans',table(['Produkt / společnost','Počáteční výše','Sjednáno','Měsíční splátka / vklad','Den platby','Poznámka'],d.rows.loans.filter(r=>r.selected).map(r=>[r.product+' · '+r.company,money(r.initial),date(r.date),money(r.payment),r.day||'Neuvedeno',r.note])));
  if(d.sections.investments)content+=section('investments',inv+d.rows.investments.filter(r=>r.selected&&r.note).map(r=>`<p><b>${esc(r.product)}</b> · ${esc(r.note)}</p>`).join(''));
  if(d.sections.pensions)content+=section('pensions',table(['Produkt','Společnost','Od kdy','Aktuální hodnota','Hodnota k datu','Poznámka'],d.rows.pensions.filter(r=>r.selected).map(r=>[r.product,r.company,date(r.date),money(r.value),date(r.valueDate),r.note]))+`<aside class=complete-cta><h3>${t('Jak může vypadat Váš státní důchod?','Jak může vypadat Tvůj státní důchod?')}</h3><p>V aplikaci IDA od ČSSZ si po přihlášení ${t('ověříte','ověříš')} evidované doby pojištění a orientační odhad důchodu. Konečná výše se stanoví až při jeho přiznání.</p><a href="https://eportal.cssz.cz/web/portal/-/sluzby/informativni-duchodova-aplikace" target="_blank" rel="noopener noreferrer">Otevřít IDA na ePortálu ČSSZ ↗</a></aside>`);
  if(d.sections.closing)content+=`<section class=complete-cta><h2>${t('Aby se v tom vyznali i Vaši blízcí','Aby se v tom vyznali i Tvoji blízcí')}</h2><p>${esc(d.closing).replace(/\n/g,'<br>')}</p><a class=complete-button href="${esc(familyLink(c,d))}" target="_blank" rel="noopener noreferrer">Zajímá mě dědický a krizový plán</a><p class=note>${t('Dotazník otevřete na telefonu i počítači. Po vyplnění stáhněte odpovědi a zašlete je na','Dotazník otevřeš na telefonu i počítači. Po vyplnění stáhni odpovědi a pošli mi je na')} ${esc(clientSenderEmail(c))}. Samotné otevření ani stažení nic neodesílá.</p></section>`;
  return `<!doctype html><html lang=cs><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><meta name=referrer content=no-referrer><title>Finanční přehled · ${esc(d.contact.name)}</title><style>${styles}\n${css()}</style></head><body><nav class=complete-tools><button onclick="window.print()">Tisk / Uložit PDF</button></nav><main class=complete-wrap>${content}<footer>${isMantra?'Mantra':'Filip Solár · FairLife'} · ${esc(clientSenderEmail(c))}<br>Údaje odpovídají evidenci k ${date(today())}. Pokud se něco změnilo, společně přehled upravíme.</footer></main>${d.sections.investments?scripts:''}</body></html>`;
 }
 function css(){return `.complete-brand{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:22px}.complete-brand>div{display:flex;align-items:center;gap:20px}.complete-logo{width:150px;height:65px;object-fit:contain}.complete-logo.mantra{width:155px;height:36px}.complete-advisor{font-size:18px;font-weight:650;color:#163c57}@media(max-width:650px){.complete-brand{align-items:flex-start;flex-direction:column;gap:8px}.complete-brand>div{gap:12px}.complete-logo{width:125px;height:52px}}body{background:#f5f8fa;color:#163c57;font:14px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif}.complete-wrap{max-width:1060px;margin:30px auto;padding:38px;background:white;border-radius:24px}.complete-contact{padding:10px 0 24px;border-bottom:2px solid #30b3c5}.complete-contact h1{font-size:36px;margin:8px 0}.complete-page{padding:28px 0}.complete-page h2{font-size:27px;margin:8px 0 14px}.eyebrow{text-transform:uppercase;letter-spacing:.12em;color:#54829d;font-size:10px}.complete-page table{width:100%;border-collapse:collapse;font-size:12px}.complete-page th{text-align:left;color:#5d7d93;font-size:10px;text-transform:uppercase}.complete-page td,.complete-page th{padding:12px 8px;border-bottom:1px solid #dfe8ee;overflow-wrap:anywhere}.complete-cta{padding:26px;border-radius:20px;background:#edf7f9;margin:20px 0;break-inside:avoid}.complete-button{display:inline-block;background:#174f73;color:white;padding:12px 20px;border-radius:12px;text-decoration:none}.complete-tools{max-width:1100px;margin:20px auto}.complete-tools button{padding:12px 18px;border:0;border-radius:12px;background:#174f73;color:white;cursor:pointer}.complete-wrap footer{margin-top:25px;font-size:11px;color:#607b90}.complete-wrap .card{box-shadow:none}.complete-wrap .report-selection{display:none}.table-wrap{overflow:auto}thead{display:table-header-group}tr{break-inside:avoid}@media(max-width:650px){.complete-wrap{padding:16px;margin:8px}.complete-contact h1{font-size:28px}.complete-cta{padding:18px}}@page{size:A4;margin:14mm}@media print{body{background:white;font-size:10pt}.complete-wrap{margin:0;padding:0;border-radius:0;max-width:none}.complete-tools{display:none}.complete-page{break-before:page;padding:0}.complete-contact+.complete-page{break-before:auto;padding-top:16px}.complete-page h2{font-size:20pt}.complete-page table{font-size:8pt}.complete-page td,.complete-page th{padding:7px 5px}.table-wrap{overflow:visible}.complete-wrap .card{break-inside:auto}.complete-wrap .portfolio-timeline{break-inside:avoid}.complete-wrap .lead{font-size:10pt}.complete-contact h1{font-size:25pt}.complete-wrap .report-fund-detail{break-inside:avoid}.complete-wrap .report-fund-details,.complete-wrap .report-provider-block{break-before:auto}.complete-wrap .portfolio-summary-card{gap:6px;padding:8px;margin:8px 0}.complete-wrap .portfolio-summary-block{padding:8px;gap:7px;grid-template-columns:1.4fr repeat(5,minmax(0,1fr))}.complete-wrap .portfolio-summary-block.total{grid-template-columns:2fr 2fr 1fr}.complete-wrap .portfolio-summary-block.fki .portfolio-summary-name{grid-column:auto}.complete-wrap .portfolio-summary-block b{font-size:11px}.complete-wrap .portfolio-summary-name h2{font-size:13px}.complete-wrap .portfolio-timeline{padding:8px;margin:8px 0}.complete-wrap .portfolio-timeline>svg{height:165px}.complete-wrap .timeline-allocation{grid-template-columns:90px 1fr;padding-top:7px;gap:10px}.complete-wrap .timeline-donut{width:85px;height:85px}.complete-wrap .timeline-center small{font-size:8px}.complete-wrap .timeline-center{inset:29% 15%}.complete-wrap .timeline-center b{font-size:9px}.complete-wrap .timeline-fund{padding:3px 0}.complete-wrap .timeline-readout{font-size:9px;gap:6px;padding:5px}.complete-wrap .timeline-note{font-size:8px;line-height:1.3}.complete-wrap .timeline-key{font-size:8px}.complete-wrap .portfolio-timeline h3{font-size:15px}.complete-wrap .report-area{margin:12px 0}.complete-wrap .report-fund-overview{padding:8px;margin:8px 0}.complete-wrap .report-fund-overview h2{font-size:14px}.complete-wrap .section-head{margin-bottom:5px}.complete-wrap .report-fund-overview td,.complete-wrap .report-fund-overview th{padding:5px 3px;font-size:8px}.complete-wrap [data-report-section=notice]{font-size:8px;padding:7px;margin:8px 0}a{color:#174f73}}`;}
 function history(c){return `<details><summary>Historie přehledů a odeslání</summary>${(c.completeReportHistory||[]).slice().reverse().map(r=>`<p>${esc(new Date(r.createdAt).toLocaleString('cs-CZ'))} · ${esc(r.format)}${r.sentDate?' · Odesláno '+esc(date(r.sentDate)):' · Odeslání nepotvrzeno'}</p>${r.sentDate?`<details><summary>Odeslaný e-mail</summary><p>${esc(r.to)} · ${esc(r.subject)}</p><pre style="white-space:pre-wrap">${esc(r.body)}</pre></details>`:''}`).join('')||'<p>Zatím bez vygenerovaného přehledu.</p>'}</details>`;}
 function generated(format){const c=findClient(owner),before=copy(state),r={id:crypto.randomUUID(),createdAt:new Date().toISOString(),format,settings:copy(draft)};c.completeReportHistory||=[];c.completeReportHistory.push(r);if(!persist()){state=before;return null;}return r;}
 function preview(){if(!save())return;const w=window.open('','_blank');if(!w)return alert('Povolte otevření náhledu v nové kartě.');const output=html(findClient(owner),draft);if(!generated('Náhled / podklad pro PDF')){w.close();return;}w.document.open();w.document.write(output);w.document.close();}
 function download(){if(!save())return;const output=html(findClient(owner),draft);if(!generated('HTML'))return;downloadHtmlFile(output,'klientsky-prehled-'+normId(draft.contact.name)+'.html');}
 function emailText(c,style){const informal=style==='informal',brand=clientManagementId(c)==='mantra'?'Mantra':'Filip Solár';return informal?`Ahoj,

posílám Ti přehled služeb a financí, které spolu řešíme. Na jednom místě tak najdeš vybrané smlouvy, částky a další důležité informace. Přehled je v příloze.

V klidu si ho projdi. Pokud se něco změnilo nebo Tě k něčemu napadne otázka, odpověz mi na tento e-mail. Rád to s Tebou projdu a údaje společně aktualizujeme.

Děkuji za důvěru a měj se hezky.
${brand}`:`Dobrý den,

posílám Vám přehled služeb a financí, které spolu řešíme. Na jednom místě tak najdete vybrané smlouvy, částky a další důležité informace. Přehled je v příloze.

V klidu si ho projděte. Pokud se něco změnilo nebo Vás k něčemu napadne otázka, odpovězte mi na tento e-mail. Rád to s Vámi projdu a údaje společně aktualizujeme.

Děkuji za důvěru a přeji hezký den.
${brand}`;}
 function prepareMail(){if(!save())return;const c=findClient(owner),rows=c.completeReportHistory||[];if(!rows.length)return alert('Nejprve vygenerujte HTML nebo otevřete náhled pro PDF.');mailDraft={clientId:c.id,id:crypto.randomUUID()};crmExtraModal('reportMail','Odeslat klientský přehled',`<label class=field>Přehled<select id="reportMailRecord">${rows.slice().reverse().map(r=>`<option value="${esc(r.id)}">${esc(new Date(r.createdAt).toLocaleString('cs-CZ'))} · ${esc(r.format)}${r.sentDate?' · již odesláno':''}</option>`).join('')}</select></label><label class=field>Odesílatel<input readonly value="${esc(clientSenderEmail(c))}"></label><label class=field>Komu<input id="reportMailTo" type="email" required value="${esc(c.email||'')}"></label><label class=field>Oslovení<select id="reportMailTone" onchange="CrmCompleteReport.mailTone()"><option value="formal">Vykání</option><option value="informal">Tykání</option></select></label><label class=field>Předmět<input id="reportMailSubject" value="Váš finanční přehled"></label><label class=field>Text e-mailu<textarea id="reportMailBody" rows="12"></textarea></label><p class=note>Do připraveného e-mailu přiložte stažené HTML nebo PDF vybraného přehledu. Příloha se nepřidává automaticky.</p><button class=btn onclick="CrmCompleteReport.mail()">Otevřít připravený e-mail</button><label class=field>Skutečné datum odeslání<input id="reportMailDate" type=date value="${today()}" max="${today()}" onchange="updateEmailReminder('reportMail')"></label><label class=field>Připomenout dne<input id="reportMailReminder" type=date value="${emailReminderDate(today())}" oninput="this.dataset.manual='1'"></label><label><input id="reportMailConfirmed" type=checkbox> E-mail s přiloženým přehledem jsem skutečně odeslal.</label><p class=note>Teprve potvrzení níže uloží kontakt a připomínku do historie klienta.</p><button id="reportMailSent" class="btn primary" onclick="CrmCompleteReport.sent()">E-mail odeslán klientovi</button>`);setVal('reportMailTone',tone(c,draft));mailTone();}
 function mailTone(){if(!mailDraft)return;setVal('reportMailBody',emailText(findClient(mailDraft.clientId),val('reportMailTone')));setVal('reportMailSubject',val('reportMailTone')==='informal'?'Tvůj finanční přehled':'Váš finanční přehled');}
 function mail(){if(!mailDraft||!document.getElementById('reportMailTo').reportValidity())return;prepareClientEmail(findClient(mailDraft.clientId),{externalTracking:true,to:val('reportMailTo'),subject:val('reportMailSubject'),body:val('reportMailBody')});}
 function sent(){if(!mailDraft)return;const c=findClient(mailDraft.clientId),r=c?.completeReportHistory?.find(x=>x.id===val('reportMailRecord')),sentDate=val('reportMailDate'),reminder=val('reportMailReminder');if(!r||!document.getElementById('reportMailTo').reportValidity())return;if(r.sentDate)return alert('Odeslání tohoto přehledu už je zaznamenané. Pro nové odeslání vygenerujte nový přehled.');if(!document.getElementById('reportMailConfirmed').checked)return alert('Potvrďte skutečné odeslání e-mailu s přílohou.');if(!sentDate||sentDate>today()||reminder&&reminder<sentDate)return alert('Zkontrolujte datum odeslání a připomenutí.');const before=copy(state);Object.assign(r,{sentDate,to:val('reportMailTo').trim(),subject:val('reportMailSubject'),body:val('reportMailBody'),sender:clientSenderEmail(c),tone:val('reportMailTone'),reminderDate:reminder});addActivity(c.id,'Email','Odeslán klientský finanční přehled · '+r.subject,true);Object.assign(state.activities.at(-1),{date:sentDate,completedAt:sentDate,reportId:r.id});if(reminder)state.activities.push({id:activities_aUid(),clientId:c.id,type:'Email',recordKind:'activity',date:reminder,text:'Navázat na odeslaný finanční přehled',completed:false,createdAt:today(),reportId:r.id});if(!persist()){state=before;return;}mailDraft=null;closeModal('reportMail');renderActiveView();saveToast('Odeslání přehledu a připomínka uloženy');}
 return {open,save,preview,download,defaults,html,key,prepareMail,mailTone,mail,sent};
})();
